CREATE FUNCTION transfer_aed(p_to uuid, p_amount bigint) RETURNS void AS $$
BEGIN
  UPDATE balances SET balance = balance - p_amount WHERE id = auth.uid() AND balance >= p_amount;
  IF NOT FOUND THEN RAISE EXCEPTION 'insufficient_funds'; END IF;
  UPDATE balances SET balance = balance + p_amount WHERE id = p_to;
END; $$ LANGUAGE plpgsql SECURITY DEFINER;

